import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import test from "node:test";

import { readSnapshot, validateSnapshot } from "../lib/meetings/snapshot.ts";

/**
 * **AN OLD-SCHEMA MEETINGS SNAPSHOT CANNOT BECOME CURRENT SERVING STATE.**
 * (2026-08-27.)
 *
 * `Meeting.bodyId` is what stopped 364 of 460 meetings rendering on bodies that
 * did not hold them; before it, a meeting took its body from its GEOGRAPHY.
 *
 * The snapshot is regenerated by a scheduled job and committed, so an older one
 * can arrive by an entirely ordinary route — a merge, a rebase, a revert, a
 * cron run from an older ref. A session resolved exactly that conflict by hand
 * on 2026-08-27, choosing the branch's file over main's older one. **A safety
 * property that depends on a future merge being judged correctly is not a
 * safety property**, so it is mechanical now, and this is its control.
 */

const ROOT = process.cwd();

test("the committed snapshot carries body identity on every meeting", () => {
  const snap = readSnapshot(ROOT);
  assert.ok(snap, "the committed snapshot did not load at all");
  if (!snap) return;

  const missing = snap.meetings.filter((m) => !m.bodyId);
  assert.deepEqual(
    missing.map((m) => m.id),
    [],
    `${missing.length} committed meeting(s) carry no bodyId and would take their body from geography`,
  );
  assert.ok(
    snap.meetings.length > 100,
    `only ${snap.meetings.length} meetings — this control would be near-vacuous`,
  );
});

test("PLANTED: a snapshot missing bodyId is REFUSED, not served", () => {
  /*
   * The replay. The committed file is read, one meeting is stripped of its body
   * identity exactly as a pre-`bodyId` file would be, and validation must
   * refuse it. Without this the guard could be deleted and every test would
   * still pass — the committed file has the fields, so nothing else exercises
   * the failure path.
   */
  const raw = JSON.parse(
    readFileSync(join(ROOT, "data/meetings-snapshot.json"), "utf8"),
  ) as { meetings: { bodyId?: string | null }[] };

  /* It must be VALID as it stands, or the refusal below proves nothing. */
  assert.doesNotThrow(() => validateSnapshot(structuredClone(raw)));

  const oldSchema = structuredClone(raw);
  for (const meeting of oldSchema.meetings) delete meeting.bodyId;

  assert.throws(
    () => validateSnapshot(oldSchema),
    /carry no bodyId/,
    "a snapshot with no body identity validated — the misattribution class can return through a merge",
  );
});

test("PLANTED: even ONE meeting without body identity is refused", () => {
  /*
   * A partial is not a lesser version of the same thing. One misattributed
   * meeting is one government credited with a sitting it did not hold, and a
   * threshold here would be the same "mostly fine" reasoning the render rules
   * refuse everywhere else.
   */
  const raw = JSON.parse(
    readFileSync(join(ROOT, "data/meetings-snapshot.json"), "utf8"),
  ) as { meetings: { bodyId?: string | null }[] };

  const oneMissing = structuredClone(raw);
  delete oneMissing.meetings[0].bodyId;
  assert.throws(() => validateSnapshot(oneMissing), /carry no bodyId/);
});
